component Counter(target: Number, label: String, duration: Number = 2000) {
  state n = target
  ref box
  ref obs
  ref frame
  ref start

  computed shown = `${Math.round(n).toLocaleString("es-AR")}+`

  fn tick(t) {
    if start == null { start = t }
    let p = Math.min((t - start) / duration, 1)
    n = target * (1 - Math.pow(1 - p, 3))
    if p < 1 {
      frame = requestAnimationFrame(tick)
    }
  }

  fn onSeen(entries) {
    if entries[0].isIntersecting {
      obs.disconnect()
      start = null
      frame = requestAnimationFrame(tick)
    }
  }

  mount {
    let reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if !reduce && "IntersectionObserver" in window {
      n = 0
      obs = new IntersectionObserver(onSeen, { threshold: 0.4 })
      obs.observe(box)
    }
    cleanup {
      if obs { obs.disconnect() }
      if frame { cancelAnimationFrame(frame) }
    }
  }

  style {
    .count {
      font-size: clamp(2.5rem, 8vw, 4.5rem);
      font-weight: 800;
      font-variant-numeric: tabular-nums;
      margin: 0;
    }
  }

  column ref=box align=center gap=1 pad=8 {
    title shown class="count" tag=p aria-live="polite"
    text label muted large
  }
}

