import { useEffect, useRef, useState } from "react";

function usePrefersReducedMotion(): boolean {
  const getInitial = () =>
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const [reduced, setReduced] = useState<boolean>(getInitial);

  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setReduced(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  return reduced;
}

function useInView<T extends Element>(threshold = 0.2) {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el || inView) return;
    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [threshold, inView]);

  return { ref, inView };
}

function formatNumber(n: number): string {
  return Math.round(n)
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

const cards = [
  { title: "Rápido", text: "Cargas instantáneas y respuestas en milisegundos." },
  { title: "Simple", text: "Una interfaz clara que se entiende al primer vistazo." },
  { title: "Abierto", text: "Código abierto, transparente y hecho en comunidad." },
];

function Card({
  title,
  text,
  index,
  visible,
  reduced,
}: {
  title: string;
  text: string;
  index: number;
  visible: boolean;
  reduced: boolean;
}) {
  const shown = visible || reduced;
  return (
    <article
      style={reduced ? undefined : { transitionDelay: `${index * 200}ms` }}
      className={[
        "rounded-2xl border border-white/10 bg-white/5 p-8 backdrop-blur-sm shadow-lg",
        reduced ? "" : "transition-all duration-700 ease-out",
        shown ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10",
      ].join(" ")}
    >
      <h3 className="text-2xl font-semibold text-white">{title}</h3>
      <p className="mt-3 text-slate-300">{text}</p>
    </article>
  );
}

function Counter({ target, reduced }: { target: number; reduced: boolean }) {
  const { ref, inView } = useInView<HTMLDivElement>(0.5);
  const [value, setValue] = useState(0);

  useEffect(() => {
    if (!inView) return;
    if (reduced) {
      setValue(target);
      return;
    }
    const duration = 2000;
    let start: number | null = null;
    let frame = 0;
    const step = (ts: number) => {
      if (start === null) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(target * eased);
      if (progress < 1) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [inView, reduced, target]);

  return (
    <div ref={ref} className="text-center">
      <p className="text-6xl font-extrabold tracking-tight text-white sm:text-7xl tabular-nums">
        <span aria-hidden="true">{formatNumber(value)}+</span>
        <span className="sr-only">{formatNumber(target)}+ usuarios</span>
      </p>
      <p aria-hidden="true" className="mt-2 text-lg text-slate-300">
        usuarios
      </p>
    </div>
  );
}

