import { createSignal, createEffect, onCleanup } from "solid-js";
import { useInView, prefersReducedMotion } from "./useInView";

interface Props {
  target: number;
  suffix?: string;
  label: string;
  duration?: number;
}

const formatNumber = (n: number) =>
  Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");

export default function Counter(props: Props) {
  const [setRef, inView] = useInView(0.5);
  const [value, setValue] = createSignal(0);
  let started = false;
  let frame = 0;

  createEffect(() => {
    if (!inView() || started) return;
    started = true;

    if (prefersReducedMotion()) {
      setValue(props.target);
      return;
    }

    const duration = props.duration ?? 2000;
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      setValue(props.target * eased);
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
  });

  onCleanup(() => cancelAnimationFrame(frame));

  return (
    <div ref={setRef} class="mx-auto max-w-md">
      <p class="sr-only">
        Más de {formatNumber(props.target)} {props.label}
      </p>
      <p
        aria-hidden="true"
        class="bg-gradient-to-r from-indigo-400 via-fuchsia-400 to-sky-400 bg-clip-text text-7xl font-extrabold tabular-nums text-transparent sm:text-8xl"
      >
        {formatNumber(value())}
        {props.suffix ?? ""}
      </p>
      <p aria-hidden="true" class="mt-3 text-lg uppercase tracking-widest text-white/60">
        {props.label}
      </p>
    </div>
  );
}

