import { createEffect, createSignal, onCleanup } from "solid-js";
import { useInView } from "./useInView";
import { usePrefersReducedMotion } from "./motion";

const TARGET = 12000;
const DURATION = 2000;

const format = (n: number) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ".");
const easeOutCubic = (t: number) => 1 - Math.pow(1 - t, 3);

export default function Counter() {
  const [ref, inView] = useInView(0.4);
  const reduced = usePrefersReducedMotion();
  const [value, setValue] = createSignal(0);
  let started = false;
  let raf = 0;

  createEffect(() => {
    if (!inView() || started) return;
    started = true;

    if (reduced()) {
      setValue(TARGET);
      return;
    }

    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min((now - start) / DURATION, 1);
      setValue(Math.round(TARGET * easeOutCubic(t)));
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  });

  onCleanup(() => cancelAnimationFrame(raf));

  return (
    <section class="px-6 pb-24 pt-8">
      <div
        ref={ref}
        class="mx-auto max-w-3xl rounded-3xl border border-white/10 bg-gradient-to-br from-indigo-600/20 to-sky-500/10 p-12 text-center"
      >
        <p class="text-6xl font-extrabold tabular-nums tracking-tight sm:text-7xl" aria-hidden="true">
          {format(value())}+
        </p>
        <p class="sr-only">Más de 12.000 usuarios</p>
        <p class="mt-3 text-lg text-slate-300" aria-hidden="true">
          usuarios ya confían en Nimbus
        </p>
      </div>
    </section>
  );
}
